window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-371e2575823e1b36"]={"versions": [{"id": "FIG-371e2575823e1b36", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Beziehungen zwischen Modul-Einsprungpunkten (<code>BswModuleEntry</code>) innerhalb des AUTOSAR-Standardisierungstemplates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es spezifiziert das Metamodell zur Bündelung und Typisierung von Abhängigkeiten bzw. Ableitungsbeziehungen (<code>BswEntryRelationship</code>) zwischen BSW-Funktionen im Kontext von <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEntryRelationshipSet</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Aggregiert über die Komposition <code>+bswEntryRelationship</code> mit Kardinalität <code>1..*</code> Instanzen von <code>BswEntryRelationship</code>.</li>\n<li><strong><code>BswEntryRelationship</code></strong>: Beziehungsklasse mit dem obligatorischen Attribut <code>+ bswEntryRelationshipType : BswEntryRelationshipEnum</code>. Referenziert über gerichtete Assoziationen zwei <code>BswModuleEntry</code>-Instanzen:</li>\n<li><code>+from</code>: Kardinalität <code>1</code></li>\n<li><code>+to</code>: Kardinalität <code>1</code></li>\n<li><strong><code>BswModuleEntry</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Definiert Attribute:</li>\n<li><code>+ bswEntryKind : BswEntryKindEnum [0..1]</code></li>\n<li><code>+ callType : BswCallType</code></li>\n<li><code>+ executionContext : BswExecutionContext</code></li>\n<li><code>+ functionPrototypeEmitter : NameToken [0..1]</code></li>\n<li><code>+ isReentrant : Boolean</code></li>\n<li><code>+ isSynchronous : Boolean</code></li>\n<li><code>+ role : Identifier [0..1]</code></li>\n<li><code>+ serviceId : PositiveInteger [0..1]</code></li>\n<li><code>+ swServiceImplPolicy : SwServiceImplPolicyEnum</code></li>\n<li><strong><code>BswEntryRelationshipEnum</code></strong>: Enumeration mit dem Literal <code>derivedFrom</code>.</li>\n<li><strong><code>BswEntryKindEnum</code></strong>: Enumeration mit den Literalen <code>abstract</code> und <code>concrete</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Es beschreibt deklarative Modellbeziehungen zur Entwurfs- und Standardisierungszeit: Ein <code>BswEntryRelationshipSet</code> fasst mindestens eine gerichtete Beziehung (<code>derivedFrom</code>) zusammen, die einen Ausgangseinsprungpunkt (<code>from</code>) eindeutig auf einen Zieleinsprungpunkt (<code>to</code>) abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für BSW-Modellbeschreibungen im Standardisierungstemplate:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>BswEntryRelationshipSet</code> muss mindestens eine Beziehungsdefinition enthalten (<code>1..*</code>).</li>\n<li>Eine <code>BswEntryRelationship</code> erfordert zwingend die Angabe des Beziehungstyps sowie jeweils genau einen Quell- (<code>from: 1</code>) und einen Ziel-Eintrag (<code>to: 1</code>).</li>\n<li>Innerhalb von <code>BswModuleEntry</code> sind die Eigenschaften <code>callType</code>, <code>executionContext</code>, <code>isReentrant</code>, <code>isSynchronous</code> und <code>swServiceImplPolicy</code> Pflichtangaben (<code>1</code>).</li>\n</ul>"}, {"id": "FIG-7a4ddaac02e56bab", "releases": ["R18-10_R4.4.0_R1.5.0", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Beziehungen zwischen Modul-Einsprungpunkten (<code>BswModuleEntry</code>) innerhalb des AUTOSAR-Standardisierungstemplates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es spezifiziert das Metamodell zur Bündelung und Typisierung von Abhängigkeiten bzw. Ableitungsbeziehungen (<code>BswEntryRelationship</code>) zwischen BSW-Funktionen im Kontext von <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEntryRelationshipSet</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Aggregiert über die Komposition <code>+bswEntryRelationship</code> mit Kardinalität <code>1..*</code> Instanzen von <code>BswEntryRelationship</code>.</li>\n<li><strong><code>BswEntryRelationship</code></strong>: Beziehungsklasse mit dem obligatorischen Attribut <code>+ bswEntryRelationshipType : BswEntryRelationshipEnum</code>. Referenziert über gerichtete Assoziationen zwei <code>BswModuleEntry</code>-Instanzen:</li>\n<li><code>+from</code>: Kardinalität <code>1</code></li>\n<li><code>+to</code>: Kardinalität <code>1</code></li>\n<li><strong><code>BswModuleEntry</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Definiert Attribute:</li>\n<li><code>+ bswEntryKind : BswEntryKindEnum [0..1]</code></li>\n<li><code>+ callType : BswCallType</code></li>\n<li><code>+ executionContext : BswExecutionContext</code></li>\n<li><code>+ functionPrototypeEmitter : NameToken [0..1]</code></li>\n<li><code>+ isReentrant : Boolean</code></li>\n<li><code>+ isSynchronous : Boolean</code></li>\n<li><code>+ role : Identifier [0..1]</code></li>\n<li><code>+ serviceId : PositiveInteger [0..1]</code></li>\n<li><code>+ swServiceImplPolicy : SwServiceImplPolicyEnum</code></li>\n<li><strong><code>BswEntryRelationshipEnum</code></strong>: Enumeration mit dem Literal <code>derivedFrom</code>.</li>\n<li><strong><code>BswEntryKindEnum</code></strong>: Enumeration mit den Literalen <code>abstract</code> und <code>concrete</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Es beschreibt deklarative Modellbeziehungen zur Entwurfs- und Standardisierungszeit: Ein <code>BswEntryRelationshipSet</code> fasst mindestens eine gerichtete Beziehung (<code>derivedFrom</code>) zusammen, die einen Ausgangseinsprungpunkt (<code>from</code>) eindeutig auf einen Zieleinsprungpunkt (<code>to</code>) abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für BSW-Modellbeschreibungen im Standardisierungstemplate:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>BswEntryRelationshipSet</code> muss mindestens eine Beziehungsdefinition enthalten (<code>1..*</code>).</li>\n<li>Eine <code>BswEntryRelationship</code> erfordert zwingend die Angabe des Beziehungstyps sowie jeweils genau einen Quell- (<code>from: 1</code>) und einen Ziel-Eintrag (<code>to: 1</code>).</li>\n<li>Innerhalb von <code>BswModuleEntry</code> sind die Eigenschaften <code>callType</code>, <code>executionContext</code>, <code>isReentrant</code>, <code>isSynchronous</code> und <code>swServiceImplPolicy</code> Pflichtangaben (<code>1</code>).</li>\n</ul>"}, {"id": "FIG-a23149ace0e7749e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Beziehungen zwischen Modul-Einsprungpunkten (<code>BswModuleEntry</code>) innerhalb des AUTOSAR-Standardisierungstemplates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es spezifiziert das Metamodell zur Bündelung und Typisierung von Abhängigkeiten bzw. Ableitungsbeziehungen (<code>BswEntryRelationship</code>) zwischen BSW-Funktionen im Kontext von <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEntryRelationshipSet</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Aggregiert über die Komposition <code>+bswEntryRelationship</code> mit Kardinalität <code>1..*</code> Instanzen von <code>BswEntryRelationship</code>.</li>\n<li><strong><code>BswEntryRelationship</code></strong>: Beziehungsklasse mit dem obligatorischen Attribut <code>+ bswEntryRelationshipType : BswEntryRelationshipEnum</code>. Referenziert über gerichtete Assoziationen zwei <code>BswModuleEntry</code>-Instanzen:</li>\n<li><code>+from</code>: Kardinalität <code>1</code></li>\n<li><code>+to</code>: Kardinalität <code>1</code></li>\n<li><strong><code>BswModuleEntry</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Definiert Attribute:</li>\n<li><code>+ bswEntryKind : BswEntryKindEnum [0..1]</code></li>\n<li><code>+ callType : BswCallType</code></li>\n<li><code>+ executionContext : BswExecutionContext</code></li>\n<li><code>+ functionPrototypeEmitter : NameToken [0..1]</code></li>\n<li><code>+ isReentrant : Boolean</code></li>\n<li><code>+ isSynchronous : Boolean</code></li>\n<li><code>+ role : Identifier [0..1]</code></li>\n<li><code>+ serviceId : PositiveInteger [0..1]</code></li>\n<li><code>+ swServiceImplPolicy : SwServiceImplPolicyEnum</code></li>\n<li><strong><code>BswEntryRelationshipEnum</code></strong>: Enumeration mit dem Literal <code>derivedFrom</code>.</li>\n<li><strong><code>BswEntryKindEnum</code></strong>: Enumeration mit den Literalen <code>abstract</code> und <code>concrete</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Es beschreibt deklarative Modellbeziehungen zur Entwurfs- und Standardisierungszeit: Ein <code>BswEntryRelationshipSet</code> fasst mindestens eine gerichtete Beziehung (<code>derivedFrom</code>) zusammen, die einen Ausgangseinsprungpunkt (<code>from</code>) eindeutig auf einen Zieleinsprungpunkt (<code>to</code>) abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für BSW-Modellbeschreibungen im Standardisierungstemplate:</p>\n<ul class=\"fig-list\">\n<li>Jedes <code>BswEntryRelationshipSet</code> muss mindestens eine Beziehungsdefinition enthalten (<code>1..*</code>).</li>\n<li>Eine <code>BswEntryRelationship</code> erfordert zwingend die Angabe des Beziehungstyps sowie jeweils genau einen Quell- (<code>from: 1</code>) und einen Ziel-Eintrag (<code>to: 1</code>).</li>\n<li>Innerhalb von <code>BswModuleEntry</code> sind die Eigenschaften <code>callType</code>, <code>executionContext</code>, <code>isReentrant</code>, <code>isSynchronous</code> und <code>swServiceImplPolicy</code> Pflichtangaben (<code>1</code>).</li>\n</ul>"}, {"id": "FIG-58a5357471d81a07", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung von Beziehungen zwischen Modul-Einsprungpunkten (<code>BswModuleEntry</code>) innerhalb des AUTOSAR-Standardisierungstemplates (<code>AUTOSAR_TPS_StandardizationTemplate</code>). Es spezifiziert das Metamodell zur Bündelung und Typisierung von Abhängigkeiten bzw. Ableitungsbeziehungen (<code>BswEntryRelationship</code>) zwischen BSW-Funktionen im Kontext von <code>ARElement</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metamodell-Elemente:</p>\n<ul class=\"fig-list\">\n<li><strong><code>BswEntryRelationshipSet</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Aggregiert über die Komposition <code>+bswEntryRelationship</code> mit Kardinalität <code>0..*</code> Instanzen von <code>BswEntryRelationship</code>.</li>\n<li><strong><code>BswEntryRelationship</code></strong>: Beziehungsklasse mit dem optionalen Attribut <code>+ bswEntryRelationshipType: BswEntryRelationshipEnum [0..1]</code>. Referenziert über gerichtete Assoziationen Instanzen von <code>BswModuleEntry</code>:</li>\n<li><code>+from</code>: Kardinalität <code>0..1</code></li>\n<li><code>+to</code>: Kardinalität <code>0..1</code></li>\n<li><strong><code>BswModuleEntry</code></strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>. Definiert Attribute:</li>\n<li><code>+ bswEntryKind: BswEntryKindEnum [0..1]</code></li>\n<li><code>+ callType: BswCallType [0..1]</code></li>\n<li><code>+ executionContext: BswExecutionContext [0..1]</code></li>\n<li><code>+ functionPrototypeEmitter: NameToken [0..1]</code></li>\n<li><code>+ isReentrant: Boolean [0..1]</code></li>\n<li><code>+ isSynchronous: Boolean [0..1]</code></li>\n<li><code>+ role: Identifier [0..1]</code></li>\n<li><code>+ serviceId: PositiveInteger [0..1]</code></li>\n<li><code>+ swServiceImplPolicy: SwServiceImplPolicyEnum [0..1]</code></li>\n<li><strong><code>BswEntryRelationshipEnum</code></strong>: Enumeration mit dem Literal <code>derivedFrom</code>.</li>\n<li><strong><code>BswEntryKindEnum</code></strong>: Enumeration mit den Literalen <code>abstract</code> und <code>concrete</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell; kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Es beschreibt deklarative Modellbeziehungen zur Entwurfs- und Standardisierungszeit: Ein <code>BswEntryRelationshipSet</code> fasst mindestens eine gerichtete Beziehung (<code>derivedFrom</code>) zusammen, die einen Ausgangseinsprungpunkt (<code>from</code>) eindeutig auf einen Zieleinsprungpunkt (<code>to</code>) abbildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für BSW-Modellbeschreibungen im Standardisierungstemplate:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>BswEntryRelationshipSet</code> kann optional leer sein oder mehrere Beziehungen enthalten (<code>0..*</code>).</li>\n<li>Innerhalb von <code>BswEntryRelationship</code> sind der Beziehungstyp <code>bswEntryRelationshipType</code> sowie die Referenzen auf Quell- (<code>from</code>) und Ziel-Einträge (<code>to</code>) optional (<code>[0..1]</code>).</li>\n<li>In <code>BswModuleEntry</code> sind sämtliche dargestellten Attribute optional (<code>[0..1]</code>), was die Modellierung unvollständiger Blueprints oder schrittweise verfeinerter Moduleinträge erlaubt.</li>\n</ul>"}], "trans": [{"from": "FIG-371e2575823e1b36", "to": "FIG-7a4ddaac02e56bab", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Formatierung der Attribut- und Rollenbezeichner: Im Attribut <code>+ bswEntryRelationshipType: BswEntryRelationshipEnum</code> der Klasse <code>BswEntryRelationship</code> sowie bei Attributen der Klasse <code>BswModuleEntry</code> (<code>callType</code>, <code>executionContext</code>, <code>isReentrant</code>, <code>isSynchronous</code>, <code>role</code>, <code>serviceId</code>, <code>swServiceImplPolicy</code>) wurde das Leerzeichen nach dem Doppelpunkt vereinheitlicht bzw. das Layout minimal nachgerendert.</li>\n<li>Typographisches Neu-Rendering ohne semantische Änderung an Modellelementen oder Multiplizitäten.</li>\n</ul>"}, {"from": "FIG-7a4ddaac02e56bab", "to": "FIG-a23149ace0e7749e", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a23149ace0e7749e", "to": "FIG-7a4ddaac02e56bab", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7a4ddaac02e56bab", "to": "FIG-58a5357471d81a07", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Komposition <code>bswEntryRelationship</code>: Multiplizität an <code>BswEntryRelationshipSet</code> von <code>1..<em></code> auf <code>0..</em></code> gelockert.</li>\n<li>Klasse <code>BswEntryRelationship</code>: Attribut <code>bswEntryRelationshipType: BswEntryRelationshipEnum</code> erhält Multiplizität <code>[0..1]</code> (zuvor obligatorisch <code>1</code>).</li>\n<li>Assoziation <code>+from</code>: Multiplizität zu <code>BswModuleEntry</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>Assoziation <code>+to</code>: Multiplizität zu <code>BswModuleEntry</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>Klasse <code>BswModuleEntry</code>: Attribute <code>callType</code>, <code>executionContext</code>, <code>isReentrant</code>, <code>isSynchronous</code> und <code>swServiceImplPolicy</code> erhalten jeweils die Multiplizität <code>[0..1]</code> (zuvor obligatorisch <code>1</code>).</li>\n</ul>"}]};
